//! Original AFEE40 packed property append and AFFCB0 action propagation.
//! Allocator and nonzero owner update remain mandatory services.
use std::collections::{BTreeMap,BTreeSet};
use crate::{audio_bus_bank::Error,audio_plugin_factory::Memory};
use crate::audio_path_source_virtual_cleanup::{get,put,live};
use crate::audio_path_source_action_list_cleanup as actions;
use crate::audio_path_source_terminal_cleanup as terminal;
pub trait Services:actions::Services{
 /// The allocator must expose its actual physical block in the canonical map.
 fn allocate_property(&mut self,pool:u32,size:u32,m:&mut BTreeMap<u32,Memory>,dead:&mut BTreeSet<u32>)->Result<Option<u32>,Error>;
 fn observe_copy(&mut self,_dst:u32,_src:u32,_n:u32,_m:&BTreeMap<u32,Memory>){}
 fn observe_append(&mut self,_slot:u32,_ty:u32,_m:&BTreeMap<u32,Memory>){}
 fn observe_property_owner_update(&mut self,_manager:u32,_owner:u32,_ty:u32,_value_bits:u32,_memory:&BTreeMap<u32,Memory>){}
 fn observe_action_owner_release(&mut self,_action:u32,_m:&BTreeMap<u32,Memory>){}
 fn update_property_owner(&mut self,manager:u32,owner:u32,ty:u32,value_bits:u32,m:&mut BTreeMap<u32,Memory>,dead:&mut BTreeSet<u32>)->Result<(),Error>;
}
fn copy(m:&mut BTreeMap<u32,Memory>,dead:&BTreeSet<u32>,dst:u32,src:u32,n:u32,s:&mut impl Services)->Result<(),Error>{
 s.observe_copy(dst,src,n,m);if n==0{return Ok(());}if (dst as u64)<src as u64+n as u64 && (src as u64)<dst as u64+n as u64{return Err(Error::Backend("overlapping native memcpy is unqualified"));}
 let bytes=live(m,dead,src,n as usize)?.to_vec();live(m,dead,dst,n as usize)?;let base=*m.range(..=dst).next_back().ok_or(Error::UnresolvedReference)?.0;let offset=dst.wrapping_sub(base)as usize;m.get_mut(&base).unwrap().raw[offset..offset+n as usize].copy_from_slice(&bytes);Ok(())
}
/// Returns the new8-byte pair without initializing its float/owner words.
/// Type insertion uses the low byte; the stored count wraps255 to0.
pub fn append(m:&mut BTreeMap<u32,Memory>,dead:&mut BTreeSet<u32>,slot:u32,ty:u32,pool:u32,s:&mut impl Services)->Result<Option<u32>,Error>{
 let old=get(m,dead,slot,4)?;let count=if old==0{0}else{get(m,dead,old,1)?};let aligned=(count+5)&!3;let pair_bytes=count*8;let size=aligned+8+pair_bytes;
 let Some(new)=s.allocate_property(pool,size,m,dead)?else{return Ok(None);};if new==0{return Err(Error::InvalidAllocation);}live(m,dead,new,size as usize)?;
 if old!=0{copy(m,dead,new.wrapping_add(1),old.wrapping_add(1),count,s)?;copy(m,dead,new.wrapping_add(aligned),old.wrapping_add((count+4)&!3),pair_bytes,s)?;live(m,dead,old,1)?;s.free(pool,old,m)?;dead.insert(old);}
 put(m,dead,new.wrapping_add(count+1),1,ty)?;put(m,dead,new,1,count.wrapping_add(1)&255)?;put(m,dead,slot,4,new)?;Ok(Some(new.wrapping_add(aligned+pair_bytes)))
}
fn find(m:&BTreeMap<u32,Memory>,dead:&BTreeSet<u32>,blob:u32,ty:u32)->Result<Option<u32>,Error>{if blob==0{return Ok(None);}let count=get(m,dead,blob,1)?;
 // Original lookup reads the first type even for a present zero-count blob.
 for i in 0..count.max(1){if get(m,dead,blob.wrapping_add(i+1),1)?==ty{return Ok(Some(blob.wrapping_add(((count+4)&!3)+i*8)));}}Ok(None)
}
/// Execute the nonempty action/property walk, then the actual current-class CC.
pub fn query(m:&mut BTreeMap<u32,Memory>,dead:&mut BTreeSet<u32>,source:u32,pool:u32,owner_manager:u32,s:&mut impl Services)->Result<(),Error>{query_impl(m,dead,source,pool,owner_manager,s,None,None)}
/// Compose nonempty D0 with real AF5670 owner setup and AF5B90 release.
pub fn query_native_owners(m:&mut BTreeMap<u32,Memory>,dead:&mut BTreeSet<u32>,source:u32,pool:u32,owner_manager:u32,context:crate::audio_path_property_owner_update::Context,s:&mut impl Services)->Result<(),Error>{query_impl(m,dead,source,pool,owner_manager,s,Some(context),None)}
/// Actual property owner update and input9C retirement share canonical storage.
pub fn query_native_inputs<S:Services+crate::audio_path_source_virtual_cleanup::InputReleaseServices>(m:&mut BTreeMap<u32,Memory>,dead:&mut BTreeSet<u32>,source:u32,pool:u32,owner_manager:u32,context:crate::audio_path_property_owner_update::Context,s:&mut S)->Result<(),Error>{query_impl(m,dead,source,pool,owner_manager,s,Some(context),Some(terminal::release_action_owners_native_inputs::<S>))}
pub fn query_native_input_graph<S:Services+crate::audio_path_source_virtual_cleanup::InputReleaseServices>(m:&mut BTreeMap<u32,Memory>,dead:&mut BTreeSet<u32>,source:u32,pool:u32,owner_manager:u32,context:crate::audio_path_property_owner_update::Context,s:&mut S)->Result<(),Error>{query_impl(m,dead,source,pool,owner_manager,s,Some(context),Some(terminal::release_action_owners_recursive_inputs::<S>))}
fn query_impl<S:Services>(m:&mut BTreeMap<u32,Memory>,dead:&mut BTreeSet<u32>,source:u32,pool:u32,owner_manager:u32,s:&mut S,native_owner:Option<crate::audio_path_property_owner_update::Context>,native_input:Option<fn(&mut BTreeMap<u32,Memory>,&mut BTreeSet<u32>,u32,u32,u32,&mut S)->Result<(),Error>>)->Result<(),Error>{
 let vt=get(m,dead,source,4)?;if vt!=0xff1cd8&&vt!=0xff10f0{return Err(Error::Backend("sourceD0 class is unqualified"));}
 let mut action=get(m,dead,source.wrapping_add(16),4)?;let mut seen=BTreeSet::new();while action!=0{if !seen.insert(action){return Err(Error::CyclicList);}let base=get(m,dead,action.wrapping_add(20),4)?;let count=get(m,dead,action.wrapping_add(24),4)?;let key=get(m,dead,action.wrapping_add(36),4)?;if count!=0{live(m,dead,base,(count as usize).checked_mul(12).ok_or(Error::InvalidAllocation)?)?;}
 let mut child=0;for i in 0..count{let entry=base.wrapping_add(i*12);if get(m,dead,entry,4)?==key{child=get(m,dead,entry.wrapping_add(4),4)?;break;}}
 if child!=0{let blob=get(m,dead,child.wrapping_add(16),4)?;let count=if blob==0{0}else{get(m,dead,blob,1)?};let values=blob.wrapping_add((count+4)&!3);for i in 0..count{let ty=get(m,dead,blob.wrapping_add(i+1),1)?;let value=get(m,dead,values.wrapping_add(i*4),4)?;let slot=action.wrapping_add(16);let blob=get(m,dead,slot,4)?;if let Some(pair)=find(m,dead,blob,ty)?{let owner=get(m,dead,pair.wrapping_add(4),4)?;if owner!=0{if let Some(context)=native_owner{s.observe_property_owner_update(owner_manager,owner,ty,value,m);crate::audio_path_property_owner_update::update(m,dead,owner,ty,value,0,4,0,context)?;}else{s.update_property_owner(owner_manager,owner,ty,value,m,dead)?;}}else{put(m,dead,pair,4,value)?;}}
 else{s.observe_append(slot,ty,m);if let Some(pair)=append(m,dead,slot,ty,pool,s)?{put(m,dead,pair.wrapping_add(4),4,0)?;put(m,dead,pair,4,value)?;}}
 }}else{s.observe_action_owner_release(action,m);if let Some(release)=native_input{release(m,dead,action,owner_manager,pool,s)?;}else{terminal::release_action_owners(m,dead,action,owner_manager,s)?;}let blob=get(m,dead,action.wrapping_add(16),4)?;if blob!=0{let count=get(m,dead,blob,1)?;let base=blob.wrapping_add((count+4)&!3);for i in 0..count{put(m,dead,base.wrapping_add(i*8),4,0)?;}}}
 action=get(m,dead,action.wrapping_add(8),4)?;
 }actions::invalidate_source_voices(m,dead,source,s)
}
